from pathlib import Path
import json,shutil
root=Path('work/minecraft-smoke');p=root/'shaderpacks'
for name,prefs in {'Clear-Max':'WATER_VISIBILITY=16.00\n','Exaggerated-Water':'WATER_DISTORTION=1.60\nRIPPLE_HEIGHT=2.20\n'}.items():
 f=p/('Stratus-1.5.0-'+name+'.zip');shutil.copyfile('outputs/Stratus-1.5.0.zip',f);f.with_suffix('.zip.txt').write_text('SKY_AMBIENT=1.60\n'+prefs)
(p/'Stratus-1.5.0-Low-Clouds.zip.txt').write_text('SKY_AMBIENT=1.60\nCLOUD_ALTITUDE=64.0\nCLOUD_THICKNESS=20.0\n')
a=[];captures=[]
def cmd(s):a.append('CMD '+s)
def wait(n):a.append('WAIT '+str(n))
def shot(n,group,note):a.extend(['SHOT v150-'+n,'WAIT 2']);captures.append({'name':n,'group':group,'note':note})
def camera(s,delay=5):cmd('tp ShaderCheck '+s);wait(delay)
def pack(s=''):a.extend(['PACK Stratus-1.5.0'+('-'+s if s else '')+'.zip','RESUME'])
pack();a.append('HUD hide');cmd('weather clear');cmd('time set 3000')
camera('184 109 45 0 26',8);shot('material-wet','Materials','Broad film and material absorption on whole faces; dirt, timber, stone/ore, polished stone, iron, glazed ceramic, sandstone.')
pack('Absorption-Only');camera('184 109 45 0 26',3);shot('material-absorption-only','Materials','Wet sheen disabled: absorbent substrate darkening, with nonabsorbing iron/glazed ceramic unchanged.')
pack('Dry');camera('184 109 45 0 26',3);shot('material-dry','Materials','Master dampness disabled, same geometry and lighting.')
pack();camera('184 103.3 45 0 4',3);shot('material-grazing','Materials','Grazing view shows a broad film over full outdoor faces, including smooth nonabsorbing material.')
cmd('weather rain');wait(14);shot('material-rain','Materials','Rain strengthens wetting without a corner-retention mask.')
cmd('weather clear');wait(10)
camera('156 105 43 0 35');shot('wood-above','Water','Reference-quality refraction through submerged logs, beam, stairs, slabs, fence gaps and glass.')
pack('No-Refraction');camera('156 105 43 0 35',3);shot('wood-unbent','Water','Unbent control of the identical three-dimensional wooden fixture.')
pack();camera('156 100 44 0 8',4);shot('wood-underwater','Water','Submerged geometry, water/air interface and underwater reflection.')
camera('149 103 45 -25 4');shot('wood-grazing','Water','Grazing transmission over varied receiver depths and normals.')
camera('155.5 101.2 44 0 -25',4);shot('waterline-below','Water','Eye just below the waterline: Snell window and TIR outside its critical angle.')
camera('155.5 101.4 44 0 -25',4);shot('waterline-above','Water','Eye just above the interface, using the opposite air/water IOR direction.')
camera('146.2 103 43 -25 38');shot('water-shore-corner','Water','Water silhouette and receiver transitions at a nearby bank/corner.')
camera('156 105 51 125 42');shot('wood-reverse-angle','Water','Opposite-angle view of submerged steps, logs and fence gaps.')
pack('Clear-Max');camera('156 105 43 0 35',3);shot('water-clarity-max','Settings','Expanded water-clarity maximum16.00, compared with the default1.70.')
pack('Exaggerated-Water');camera('156 105 43 0 35',3);shot('water-artistic-range','Settings','Deliberately exaggerated refraction/ripples; physical ray bending remains the1.00 default.')
pack()
for biome,name in [('swamp','swamp'),('warm_ocean','warm-ocean'),('frozen_ocean','frozen-ocean'),('river','river')]:
 cmd('fillbiome 144 90 40 168 112 64 minecraft:'+biome);camera('156 105 43 0 35',10);shot('water-'+name,'Water','Controlled biome tint and sediment comparison; random_tick_speed0 prevents freezing.')
cmd('weather rain');wait(14);shot('water-rain','Water','Rain runoff/turbidity and ripple response in exposed river water.');cmd('weather clear');wait(10)
camera('104 104 90 0 9');shot('reflection-lake','Water','Opaque terrain, colored columns and cow reflected across water.')
pack('No-Reflections');camera('104 104 90 0 9',3);shot('reflection-control','Water','Reflection-disabled control; total internal reflection remains physical underwater.')
pack();camera('104 99 94 0 -15',4);shot('deep-underwater','Water','Deep water optical path, interface and distant wall reflection precision.')
camera('13 90 -3 0 0');shot('shallow-underwater','Water','Shallow basin sides/floor and consistent attenuation.')
cmd('fill -15 104 2 -11 104 4 minecraft:water');camera('-18 100 -4 -35 8',8);shot('waterfall-sides','Water','Flowing levels and a thin falling sheet against terrain and sky.')
camera('-14 106 -3 0 45');shot('waterfall-top','Water','Source and flowing transition over the waterfall lip.')
cmd('fill 80 108 30 96 110 46 minecraft:stone');cmd('setblock 88 101 38 minecraft:water');camera('88 102 34 0 6',7);shot('cave-water','Water','Sheltered dark water; no outdoor rain-runoff or fog veil.')
cmd('setblock 88 101 38 minecraft:sea_lantern');wait(6);shot('cave-lit','Water','Local block light and Snell transmission onto a striped floor.')
cmd('fill 80 108 30 96 110 46 minecraft:air');cmd('setblock 88 101 38 minecraft:water');camera('88 106 32 0 55');shot('striped-floor','Water','Straight floor stripes reveal refraction folding or screen-edge discontinuities.')
cmd('time set 18000');camera('156 105 43 0 35',6);shot('water-night','Water','Night water lighting and reflection fallback.');cmd('time set 3000')
pack('Low-Clouds');camera('104 185 90 0 80',6);shot('water-above-cloud','Water','Low cloud volume stays below the elevated lake; view down through the water/cloud overlap.')
pack();camera('200 145 200 0 -35',6);shot('cloud-below','Sky','High-resolution rounded cloud structure from beneath, separated from low fog.')
camera('200 256 200 0 0',6);shot('cloud-inside','Sky','Camera within the continuous three-dimensional cloud volume.')
camera('200 330 200 0 30',6);shot('cloud-above','Sky','Rounded main cloud tops and separate high-altitude cirrus.')
camera('200 420 200 0 25',6);shot('cirrus-above','Sky','View down across the high cloud layer.')
pack('Cloud-Strong');camera('200 145 200 0 -35',5);shot('cloud-detail-range','Settings','Higher cloud density2.20 and detail1.70 demonstrate independent tuning.')
pack();camera('-110 130 -100 -45 25',12);shot('fog-landscape','Atmosphere','Default valley fog, with nearer pockets and preserved foreground clarity.')
camera('-110 92 -100 -45 5',8);shot('fog-near','Atmosphere','Fog between nearby and deeper tree layers, anchored in world space.')
pack('Fog-Strong');camera('-110 110 -100 -45 15',8);shot('fog-controls','Settings','Fog altitude96, near range8 and density1.50 as an explicit stronger artistic setting.')
pack('Vanilla-Sky');cmd('time set 3000');camera('0 110 0 -90 -40',6);shot('vanilla-sky','Sky','Actual vanilla clouds and textured sun remain independent options.')
cmd('time set 18000');camera('0 110 0 0 -85',6);shot('vanilla-moon','Sky','Actual textured moon, without a black rectangular background.')
pack();cmd('time set 3000');cmd('execute in minecraft:the_nether run tp ShaderCheck 0 103 -5 0 18');wait(12);a.append('RESUME');wait(3);shot('nether','Regression','Nether pipeline and dimension-specific atmosphere after the shared-library changes.')
cmd('execute in minecraft:the_end run tp ShaderCheck 0 123 -5 0 18');wait(12);a.append('RESUME');wait(3);shot('end','Regression','End pipeline and fallback lighting.')
cmd('execute in minecraft:overworld run tp ShaderCheck -8 100 2 0 12');wait(12);a.append('RESUME');wait(3);shot('entities','Regression','Entities retain form lighting and stay outside material pore-darkening.')
cmd('tp ShaderCheck 0 97 5 0 5');cmd('setblock 0 97 9 minecraft:stone');cmd('setblock 0 97 9 minecraft:air destroy');shot('breaking-particles','Regression','Breaking particles after the material/refraction updates.')
cmd('summon minecraft:snowball -1 98.3 9 {NoGravity:1b,Tags:["stratus150_projectile"]}');cmd('summon minecraft:egg 0 98.3 9 {NoGravity:1b,Tags:["stratus150_projectile"]}');cmd('summon minecraft:ender_pearl 1 98.3 9 {NoGravity:1b,Tags:["stratus150_projectile"]}');wait(3);shot('projectiles','Regression','Snowball, egg and pearl remain shaded normally.');cmd('kill @e[tag=stratus150_projectile]')
cmd('time set 18000');camera('0 96 5 0 10',6);shot('bloom-fireflies','Regression','Emissive/firefly-bush and restrained factory bloom.');cmd('time set 3000')
cmd('gamerule minecraft:random_tick_speed 3');camera('156 105 43 0 35',8);a.append('STATE');a.append('DONE v150-regression-complete')
q=root/'qa-request.txt';assert not q.exists();q.write_text('\n'.join(a)+'\n');Path('work/stratus-check/captures-150.json').write_text(json.dumps(captures,indent=2)+'\n');print('Queued',len(captures),'scene/control captures;',len(a),'steps. All edits are in the isolated copied world.')
